import sys
from collections import defaultdict, deque

def find_minimal_k_coverings(n1, n2, edges):
    adj_list = defaultdict(list)
    edge_indices = {}
    for idx, (u, v) in enumerate(edges, 1):
        adj_list[u].append((v, idx))
        adj_list[v].append((u, idx))
        edge_indices[(u, v)] = idx

    def bfs(source, k):
        queue = deque([source])
        visited = set()
        parent = {source: None}
        visited.add(source)
        while queue:
            node = queue.popleft()
            for neighbor, edge_idx in adj_list[node]:
                if neighbor not in visited:
                    visited.add(neighbor)
                    parent[neighbor] = (node, edge_idx)
                    if len([e for n, e in adj_list[neighbor] if n in visited]) >= k:
                        path_edges = []
                        current = neighbor
                        while current != source:
                            prev, edge_idx = parent[current]
                            path_edges.append(edge_idx)
                            current = prev
                        return path_edges
                    queue.append(neighbor)
        return []

    def find_covering(k):
        covering = set()
        degree = [0] * (n1 + n2 + 1)
        for u in range(1, n1 + 1):
            for v, _ in adj_list[u]:
                degree[u] += 1
                degree[v] += 1

        while True:
            found = False
            for node in range(1, n1 + n2 + 1):
                if degree[node] < k:
                    path = bfs(node, k)
                    if path:
                        found = True
                        covering.update(path)
                        for edge_idx in path:
                            u, v = next((u, v) for u, v in edge_indices if edge_indices[(u, v)] == edge_idx)
                            degree[u] -= 1
                            degree[v] -= 1
            if not found:
                break

        return sorted(covering)

    min_degree = min(min(sum(1 for _ in adj_list[u]) for u in range(1, n1 + 1)), min(sum(1 for _ in adj_list[v]) for v in range(n1 + 1, n1 + n2 + 1)))
    results = []
    for k in range(min_degree + 1):
        covering = find_covering(k)
        results.append(f"{len(covering)} {' '.join(map(str, covering))}")

    return '\n'.join(results)

input = sys.stdin.read().split()
n1, n2, m = map(int, input[:3])
edges = list(zip(map(int, input[3::2]), map(int, input[4::2])))
print(find_minimal_k_coverings(n1, n2, edges))
